import{_ as t,o as i,c as n,a2 as o}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Housing and Environmental Protection","description":"","frontmatter":{},"headers":[],"relativePath":"en/0039-住房与环境保障.md","filePath":"en/0039-住房与环境保障.md"}'),a={name:"en/0039-住房与环境保障.md"};function s(r,e,l,c,d,u){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="housing-and-environmental-protection" tabindex="-1">Housing and Environmental Protection <a class="header-anchor" href="#housing-and-environmental-protection" aria-label="Permalink to &quot;Housing and Environmental Protection&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Content</th></tr></thead><tbody><tr><td>Document No.</td><td>39</td></tr><tr><td>Module</td><td>Civilization Typologies and Social Systems</td></tr><tr><td>Keywords</td><td>Housing Guarantee, Environmental Protection, Ecological Symbiosis, Livable Spaces, Sustainable Development</td></tr></tbody></table><h2 id="i-core-concepts-of-housing-and-environmental-protection" tabindex="-1">I. Core Concepts of Housing and Environmental Protection <a class="header-anchor" href="#i-core-concepts-of-housing-and-environmental-protection" aria-label="Permalink to &quot;I. Core Concepts of Housing and Environmental Protection&quot;">​</a></h2><p>&quot;Every resident shall have a dwelling&quot; is a basic livelihood issue that every civilization must face. In the era of the Predatory Cultivation System, housing and land were monopolized by a few powerhouses and sects, and the masses at the bottom were often homeless, forced to cultivate and live in harsh environments. More seriously, predatory cultivation caused tremendous damage to the environment — spirit veins were over-exploited, ecology was severely polluted, and planetary resources were consumed in a predatory manner, turning many once-livable planets into barren wastelands.</p><p>After the establishment of the Anchor Symbiotic Civilization, housing guarantee and environmental protection became core contents of social institution building. The core concept of housing and environmental protection can be summarized in sixteen characters: &quot;A Dwelling for Every Resident, Ecological Symbiosis, Sustainable Development, Livable for the Myriad Races.&quot;</p><p>The core goals of housing and environmental protection include:</p><ol><li><strong>Guaranteeing the basic right to housing</strong>: ensure that every symbiotic life can obtain decent, safe, and suitable housing, and that housing problems do not affect survival and evolution</li><li><strong>Protecting the ecological environment</strong>: establish a complete environmental protection system, maintain ecological balance, and prevent cultivation activities from damaging the environment</li><li><strong>Building livable spaces</strong>: through scientific planning and technological means, build livable spaces suitable for cultivation and living</li><li><strong>Realizing sustainable development</strong>: while meeting the needs of the present generation, do not harm the ability of future generations to meet their needs, realizing the sustainable use of resources and the environment</li><li><strong>Promoting livability for the Myriad Races</strong>: housing and environmental construction fully consider the physiological characteristics and living habits of different races, ensuring that the Myriad Races can all live comfortably</li></ol><h2 id="ii-the-housing-guarantee-system" tabindex="-1">II. The Housing Guarantee System <a class="header-anchor" href="#ii-the-housing-guarantee-system" aria-label="Permalink to &quot;II. The Housing Guarantee System&quot;">​</a></h2><p>The housing guarantee system of the symbiotic civilization follows the principles of &quot;guaranteeing the basics, promoting improvement, multiple channels, and sustainability,&quot; constructing a multi-level housing supply system:</p><h3 id="_2-1-the-three-levels-of-housing-supply" tabindex="-1">2.1 The Three Levels of Housing Supply <a class="header-anchor" href="#_2-1-the-three-levels-of-housing-supply" aria-label="Permalink to &quot;2.1 The Three Levels of Housing Supply&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Level</th><th>Name</th><th>Supply Target</th><th>Housing Type</th><th>Rent/Price</th></tr></thead><tbody><tr><td>First Level</td><td>Guaranteed Housing</td><td>Low-income groups, newly initiated cultivators</td><td>Basic cultivation apartments, collective dormitories</td><td>Free or extremely low rent</td></tr><tr><td>Second Level</td><td>Improved Housing</td><td>Middle-income groups, intermediate cultivators</td><td>Standard cultivation residences, family apartments</td><td>Cost price or low rent</td></tr><tr><td>Third Level</td><td>Commercial Housing</td><td>High-income groups, advanced cultivators</td><td>High-end cultivation residences, independent cave mansions</td><td>Market price</td></tr></tbody></table><h3 id="_2-2-the-guaranteed-housing-system" tabindex="-1">2.2 The Guaranteed Housing System <a class="header-anchor" href="#_2-2-the-guaranteed-housing-system" aria-label="Permalink to &quot;2.2 The Guaranteed Housing System&quot;">​</a></h3><p>Guaranteed housing is the core of the housing guarantee system, ensuring every symbiotic life&#39;s basic right to housing:</p><ul><li><strong>Basic cultivation apartments</strong>: small apartments for newly initiated cultivators and single individuals, equipped with basic cultivation facilities, with extremely low or free rent</li><li><strong>Collective dormitories</strong>: collective accommodation for sect disciples, students, and collective workers, with shared cultivation spaces</li><li><strong>Family guaranteed housing</strong>: complete dwellings for low-income families, with moderate size and complete facilities</li><li><strong>Special guaranteed housing</strong>: adaptable housing for disabled lives, special races, elderly cultivators, and other special groups</li></ul><p>The application and allocation of guaranteed housing follow the principles of &quot;openness, fairness, and justice,&quot; with applications and reviews conducted through the symbiotic network, and allocation results made public and transparent.</p><h3 id="_2-3-the-improved-housing-system" tabindex="-1">2.3 The Improved Housing System <a class="header-anchor" href="#_2-3-the-improved-housing-system" aria-label="Permalink to &quot;2.3 The Improved Housing System&quot;">​</a></h3><p>Improved housing targets middle-income groups with a certain economic capacity, provided at cost price or low rent:</p><ul><li><strong>Standard cultivation residences</strong>: complete dwellings with independent cultivation rooms, suitable for individuals and families with a certain cultivation foundation</li><li><strong>Family apartments</strong>: medium-sized apartments suitable for families, with children&#39;s activity spaces and family cultivation areas</li><li><strong>Talent apartments</strong>: preferential housing for introduced high-level talents and professional technical personnel</li></ul><p>The supply of improved housing is dynamically adjusted according to demand, ensuring that middle-income groups can obtain suitable housing at reasonable costs.</p><h3 id="_2-4-the-commercial-housing-system" tabindex="-1">2.4 The Commercial Housing System <a class="header-anchor" href="#_2-4-the-commercial-housing-system" aria-label="Permalink to &quot;2.4 The Commercial Housing System&quot;">​</a></h3><p>Commercial housing targets high-income groups and is provided at market prices:</p><ul><li><strong>High-end cultivation residences</strong>: luxurious residences equipped with advanced cultivation facilities</li><li><strong>Independent cave mansions</strong>: cultivation cave mansions with independent space and energy supply</li><li><strong>Custom residences</strong>: special residences customized according to individual needs</li></ul><p>The transaction of commercial housing follows market rules, but the government regulates through property taxes, land management, and other means, preventing excessive housing price increases and real estate speculation.</p><h3 id="_2-5-cultivation-space-support" tabindex="-1">2.5 Cultivation Space Support <a class="header-anchor" href="#_2-5-cultivation-space-support" aria-label="Permalink to &quot;2.5 Cultivation Space Support&quot;">​</a></h3><p>Housing in the symbiotic civilization is not only living space, but also cultivation space. Every residence is equipped with corresponding cultivation facilities according to the cultivation needs of the residents:</p><ul><li><strong>Basic cultivation area</strong>: every residence has a basic cultivation area, equipped with basic energy access interfaces</li><li><strong>Energy supply</strong>: stable energy supply for residences through the Anchor Network, meeting cultivation needs</li><li><strong>Sound and energy insulation</strong>: cultivation areas have sound insulation and energy protection facilities, preventing cultivation from disturbing others</li><li><strong>Public cultivation spaces</strong>: communities have shared spaces such as public cultivation halls and cultivation equipment rooms</li></ul><h2 id="iii-the-environmental-protection-system" tabindex="-1">III. The Environmental Protection System <a class="header-anchor" href="#iii-the-environmental-protection-system" aria-label="Permalink to &quot;III. The Environmental Protection System&quot;">​</a></h2><p>The environmental protection system of the symbiotic civilization follows the principles of &quot;prevention first, comprehensive treatment, ecological restoration, and sustainable use,&quot; constructing a comprehensive environmental protection framework:</p><h3 id="_3-1-environmental-standards-and-supervision" tabindex="-1">3.1 Environmental Standards and Supervision <a class="header-anchor" href="#_3-1-environmental-standards-and-supervision" aria-label="Permalink to &quot;3.1 Environmental Standards and Supervision&quot;">​</a></h3><p>The symbiotic civilization has formulated strict environmental standards, regulating the environmental impact of cultivation and production activities:</p><ul><li><strong>Energy emission standards</strong>: strict limits on energy emissions generated during cultivation and production</li><li><strong>Resource extraction standards</strong>: regulation of the extraction of spirit veins, minerals, biological resources, etc., preventing over-exploitation</li><li><strong>Ecological protection red lines</strong>: designate ecological protection red lines, within which any destructive activity is prohibited</li><li><strong>Environmental impact assessment</strong>: major cultivation projects and construction projects must undergo environmental impact assessment</li></ul><p>Environmental protection supervision is the responsibility of dedicated environmental supervision institutions, which monitor environmental quality in real time through the symbiotic network and impose severe penalties on illegal activities.</p><h3 id="_3-2-pollution-treatment-technology" tabindex="-1">3.2 Pollution Treatment Technology <a class="header-anchor" href="#_3-2-pollution-treatment-technology" aria-label="Permalink to &quot;3.2 Pollution Treatment Technology&quot;">​</a></h3><p>The symbiotic civilization has developed advanced pollution treatment technologies:</p><ul><li><strong>Energy pollution treatment</strong>: through energy filtration, energy conversion, and other technologies, treat energy pollution generated by cultivation activities</li><li><strong>Material pollution treatment</strong>: through bioremediation, chemical treatment, physical purification, and other technologies, treat material pollution</li><li><strong>Law pollution treatment</strong>: through law stripping, law neutralization, and other technologies, treat environmental pollution caused by law erosion</li><li><strong>Ecological restoration technology</strong>: through the Life Circulation System and ecological engineering technology, restore damaged ecosystems</li></ul><h3 id="_3-3-sustainable-use-of-resources" tabindex="-1">3.3 Sustainable Use of Resources <a class="header-anchor" href="#_3-3-sustainable-use-of-resources" aria-label="Permalink to &quot;3.3 Sustainable Use of Resources&quot;">​</a></h3><p>The symbiotic civilization emphasizes the sustainable use of resources and opposes predatory development:</p><ul><li><strong>Resource extraction quotas</strong>: implement extraction quota systems for non-renewable resources, ensuring long-term resource use</li><li><strong>Resource recycling</strong>: vigorously develop resource recycling technologies, improving resource utilization efficiency</li><li><strong>Renewable energy development</strong>: actively develop renewable energy such as solar, wind, hydro, and energy-field energy</li><li><strong>Alternative resource research</strong>: research substitutes for scarce resources, reducing dependence on scarce resources</li></ul><h3 id="_3-4-ecological-protection-and-restoration" tabindex="-1">3.4 Ecological Protection and Restoration <a class="header-anchor" href="#_3-4-ecological-protection-and-restoration" aria-label="Permalink to &quot;3.4 Ecological Protection and Restoration&quot;">​</a></h3><p>The symbiotic civilization attaches great importance to ecological protection and restoration:</p><ul><li><strong>Nature reserves</strong>: establish nature reserves at all levels, protecting rare species and pristine ecosystems</li><li><strong>Ecological restoration projects</strong>: restore already-damaged ecosystems, restoring ecological balance</li><li><strong>Species protection programs</strong>: protect and breed endangered species, preventing species extinction</li><li><strong>Ecological compensation mechanism</strong>: compensate regions and groups that suffer losses due to ecological protection</li></ul><h2 id="iv-livable-space-construction" tabindex="-1">IV. Livable Space Construction <a class="header-anchor" href="#iv-livable-space-construction" aria-label="Permalink to &quot;IV. Livable Space Construction&quot;">​</a></h2><p>On the basis of housing and environmental protection, the symbiotic civilization vigorously promotes the construction of livable spaces:</p><h3 id="_4-1-urban-planning" tabindex="-1">4.1 Urban Planning <a class="header-anchor" href="#_4-1-urban-planning" aria-label="Permalink to &quot;4.1 Urban Planning&quot;">​</a></h3><p>The urban planning of the symbiotic civilization follows the principles of &quot;compact, green, intelligent, and humane&quot;:</p><ul><li><strong>Compact layout</strong>: cities adopt compact layouts, reducing land occupation and transportation energy consumption</li><li><strong>Green spaces</strong>: cities retain ample green spaces such as greenbelts, parks, and wetlands</li><li><strong>Intelligent management</strong>: through the Anchor Network and intelligent technology, realize intelligent city management</li><li><strong>Humane care</strong>: urban planning fully considers the needs of different races, ages, and ability groups</li></ul><h3 id="_4-2-cultivation-community-construction" tabindex="-1">4.2 Cultivation Community Construction <a class="header-anchor" href="#_4-2-cultivation-community-construction" aria-label="Permalink to &quot;4.2 Cultivation Community Construction&quot;">​</a></h3><p>The symbiotic civilization vigorously builds cultivation communities integrating residence, cultivation, and services:</p><ul><li><strong>Community cultivation centers</strong>: every community has a cultivation center, providing public cultivation spaces and cultivation guidance</li><li><strong>Community service centers</strong>: providing comprehensive services such as healthcare, education, commerce, and entertainment</li><li><strong>Community green spaces</strong>: communities retain ample green and leisure spaces</li><li><strong>Community culture</strong>: cultivate community culture, enhancing residents&#39; sense of belonging and cohesion</li></ul><h3 id="_4-3-cross-plane-livable-spaces" tabindex="-1">4.3 Cross-Plane Livable Spaces <a class="header-anchor" href="#_4-3-cross-plane-livable-spaces" aria-label="Permalink to &quot;4.3 Cross-Plane Livable Spaces&quot;">​</a></h3><p>With the advancement of cross-plane exploration, the symbiotic civilization has begun to build livable spaces on other planes:</p><ul><li><strong>Plane livability transformation</strong>: transform suitable planes to be livable, building new residential and cultivation spaces</li><li><strong>Ecological migration</strong>: migrate population in a planned manner from resource-strained planes to newly developed livable planes</li><li><strong>Cross-Plane housing</strong>: provide cross-plane housing guarantees for cultivators who frequently travel across planes</li></ul><h2 id="v-differences-in-housing-and-environmental-models-of-the-five-civilization-types" tabindex="-1">V. Differences in Housing and Environmental Models of the Five Civilization Types <a class="header-anchor" href="#v-differences-in-housing-and-environmental-models-of-the-five-civilization-types" aria-label="Permalink to &quot;V. Differences in Housing and Environmental Models of the Five Civilization Types&quot;">​</a></h2><p>The five symbiotic civilization types have their own characteristics in housing and environmental models:</p><table tabindex="0"><thead><tr><th>Type</th><th>Housing Model Features</th><th>Environmental Model Features</th></tr></thead><tbody><tr><td>East Asian Intensive Type</td><td>High density, intensive, collective dormitories as the main form</td><td>Strict supervision, efficient governance, rapid restoration</td></tr><tr><td>Nordic Welfare Type</td><td>High guarantee, high quality, personalized</td><td>High standards, high investment, ecology first</td></tr><tr><td>North American Pluralistic Type</td><td>Market-oriented, diversified, low density</td><td>Market-based governance, technology-driven, resource protection</td></tr><tr><td>Continental European Social Type</td><td>Social housing, cooperative housing, balanced allocation</td><td>Associational participation, deliberative governance, sustainable development</td></tr><tr><td>Developing Catch-up Type</td><td>Guarantee first, rapid construction, gradual improvement</td><td>Development and protection both emphasized, focused governance</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Housing and environmental protection are the &quot;livelihood cornerstone&quot; and &quot;ecological barrier&quot; of the Anchor Symbiotic Civilization. Through the multi-level housing guarantee system, the comprehensive environmental protection system, and scientific livable space construction, the symbiotic civilization has realized the goals of &quot;A Dwelling for Every Resident, Ecological Symbiosis, Sustainable Development, Livable for the Myriad Races.&quot; The guarantee of housing allows every symbiotic life to cultivate with peace of mind, and environmental protection lays the ecological foundation for the long-term development of the civilization. The two complement each other, jointly supporting the advancement of the Myriad Races and the sustainable development of the symbiotic civilization.</p><h2 id="related-documents" tabindex="-1">Related Documents <a class="header-anchor" href="#related-documents" aria-label="Permalink to &quot;Related Documents&quot;">​</a></h2><ul><li>45-住房保障法 (Housing Guarantee Law)</li><li>46-环境保护法 (Environmental Protection Law)</li><li>32-北欧福利型文明 (Nordic Welfare Civilization)</li></ul>',59)])])}const p=t(a,[["render",s]]);export{g as __pageData,p as default};
